   161  // Imports the given file into the given scene structure.
   162  void MDLImporter::InternReadFile(const std::string &pFile,
   163          aiScene *_pScene, IOSystem *pIOHandler) {
   164      pScene = _pScene;
   165      mIOHandler = pIOHandler;
   166      std::unique_ptr<IOStream> file(pIOHandler->Open(pFile));
   167
   168      // Check whether we can read from the file
   169      if (file.get() == nullptr) {
   170          throw DeadlyImportError("Failed to open MDL file " + pFile + ".");
   171      }
   172
   173      // This should work for all other types of MDL files, too ...
   174      // the HL1 sequence group header is one of the smallest, afaik
   175      iFileSize = (unsigned int)file->FileSize();
   176      if (iFileSize < sizeof(MDL::HalfLife::SequenceHeader_HL1)) {
   177          throw DeadlyImportError("MDL File is too small.");
   178      }
   179
   180      // delete the file buffer and cleanup.
   181      auto DeleteBufferAndCleanup = [&]() {
   182          if (mBuffer) {
   183              delete[] mBuffer;
   184              mBuffer = nullptr;
   185          }
   186          AI_DEBUG_INVALIDATE_PTR(mIOHandler);
   187          AI_DEBUG_INVALIDATE_PTR(pScene);
   188      };
   189
   190      try {
   191          // Allocate storage and copy the contents of the file to a memory buffer
   192          mBuffer = new unsigned char[iFileSize + 1];
   193          file->Read((void *)mBuffer, 1, iFileSize);
   194
   195          // Append a binary zero to the end of the buffer.
   196          // this is just for safety that string parsing routines
   197          // find the end of the buffer ...
   198          mBuffer[iFileSize] = '\0';
   199          const uint32_t iMagicWord = *((uint32_t *)mBuffer);
   200
   201          // Determine the file subtype and call the appropriate member function
   202
   203          // Original Quake1 format
   204          if (AI_MDL_MAGIC_NUMBER_BE == iMagicWord || AI_MDL_MAGIC_NUMBER_LE == iMagicWord) {
   205              ASSIMP_LOG_DEBUG("MDL subtype: Quake 1, magic word is IDPO");
   206              iGSFileVersion = 0;
   207              InternReadFile_Quake1();
   208          }
   209          // GameStudio A<old> MDL2 format - used by some test models that come with 3DGS
   210          else if (AI_MDL_MAGIC_NUMBER_BE_GS3 == iMagicWord || AI_MDL_MAGIC_NUMBER_LE_GS3 == iMagicWord) {
   211              ASSIMP_LOG_DEBUG("MDL subtype: 3D GameStudio A2, magic word is MDL2");
   212              iGSFileVersion = 2;
   213              InternReadFile_Quake1();
   214          }
   215          // GameStudio A4 MDL3 format
   216          else if (AI_MDL_MAGIC_NUMBER_BE_GS4 == iMagicWord || AI_MDL_MAGIC_NUMBER_LE_GS4 == iMagicWord) {
   217              ASSIMP_LOG_DEBUG("MDL subtype: 3D GameStudio A4, magic word is MDL3");
   218              iGSFileVersion = 3;
   219              InternReadFile_3DGS_MDL345();
   220          }
   221          // GameStudio A5+ MDL4 format
   222          else if (AI_MDL_MAGIC_NUMBER_BE_GS5a == iMagicWord || AI_MDL_MAGIC_NUMBER_LE_GS5a == iMagicWord) {
   223              ASSIMP_LOG_DEBUG("MDL subtype: 3D GameStudio A4, magic word is MDL4");
   224              iGSFileVersion = 4;
   225              InternReadFile_3DGS_MDL345();
   226          }
   227          // GameStudio A5+ MDL5 format
   228          else if (AI_MDL_MAGIC_NUMBER_BE_GS5b == iMagicWord || AI_MDL_MAGIC_NUMBER_LE_GS5b == iMagicWord) {
   229              ASSIMP_LOG_DEBUG("MDL subtype: 3D GameStudio A5, magic word is MDL5");
   230              iGSFileVersion = 5;
   231              InternReadFile_3DGS_MDL345();
   232          }
   233          // GameStudio A7 MDL7 format
   234          else if (AI_MDL_MAGIC_NUMBER_BE_GS7 == iMagicWord || AI_MDL_MAGIC_NUMBER_LE_GS7 == iMagicWord) {
   235              ASSIMP_LOG_DEBUG("MDL subtype: 3D GameStudio A7, magic word is MDL7");
   236              iGSFileVersion = 7;
   237              InternReadFile_3DGS_MDL7();
   238          }
   239          // IDST/IDSQ Format (CS:S/HL^2, etc ...)
   240          else if (AI_MDL_MAGIC_NUMBER_BE_HL2a == iMagicWord || AI_MDL_MAGIC_NUMBER_LE_HL2a == iMagicWord ||
   241                   AI_MDL_MAGIC_NUMBER_BE_HL2b == iMagicWord || AI_MDL_MAGIC_NUMBER_LE_HL2b == iMagicWord) {
   242              iGSFileVersion = 0;
   243
   244              HalfLife::HalfLifeMDLBaseHeader *pHeader = (HalfLife::HalfLifeMDLBaseHeader *)mBuffer;
   245              if (pHeader->version == AI_MDL_HL1_VERSION) {
   246                  ASSIMP_LOG_DEBUG("MDL subtype: Half-Life 1/Goldsrc Engine, magic word is IDST/IDSQ");
   247                  InternReadFile_HL1(pFile, iMagicWord);
   248              } else {
   249                  ASSIMP_LOG_DEBUG("MDL subtype: Source(tm) Engine, magic word is IDST/IDSQ");
   250                  InternReadFile_HL2();
   251              }
   252          } else {
   253              // print the magic word to the log file
   254              throw DeadlyImportError("Unknown MDL subformat " + pFile +
   255                                      ". Magic word (" + std::string((char *)&iMagicWord, 4) + ") is not known");
   256          }
   257
   258          // Now rotate the whole scene 90 degrees around the x axis to convert to internal coordinate system
   259          pScene->mRootNode->mTransformation = aiMatrix4x4(1.f, 0.f, 0.f, 0.f,
   260                  0.f, 0.f, 1.f, 0.f, 0.f, -1.f, 0.f, 0.f, 0.f, 0.f, 0.f, 1.f);
